    getPosts();

  }, []);


  return (

    <div>

      <h1>Posts</h1>

      {posts.map((post) => (

        <div key={post.id}>

          <h2>

            <Link to={`/posts/${post.id}`}>{post.title}</Link>

          </h2>

        </div>

      ))}

    </div>

  );

};


